// App icon served from the MCP host so clients (claude.ai directory, Claude apps) can show it
// as the server favicon. Same PNGs as thinkspace-app.com/favicon.png (64px) and /icon.png (512px).

const FAVICON_64_B64 = "";
const ICON_512_B64 = "";

function pngResponse(b64: string): Response {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Response(bytes, {
    headers: {
      "content-type": "image/png",
      "cache-control": "public, max-age=86400",
    },
  });
}

/** Returns a Response for /favicon.ico, /favicon.png, /icon.png; null for other paths. */
export function handleIcon(pathname: string): Response | null {
  if (pathname === "/favicon.ico" || pathname === "/favicon.png") return pngResponse(FAVICON_64_B64);
  if (pathname === "/icon.png") return pngResponse(ICON_512_B64);
  return null;
}
